def build_context(task, budget):
    ctx = [durable_rules(task.service)]      # needed before planning
    ctx.append(task_packet(task))            # request, revision, policy
    for doc in search(task.symbols):         # fetched as the task narrows
        if not allowed(task.agent, doc):
            continue                         # access checked first
        ctx.append(doc.with_source_and_version())
    gaps = task.required_inputs - covered(ctx)
    if gaps:
        return blocked(task, gaps, ask=task.owner)  # never guess
    return trim_to(ctx, budget)
